T({id:"handoff.work",name:"Hand off open work",desc:"Moves open tasks to a named person after a load check.",perm:"project.write",write:true,risk:"medium",confirm:"ask",int:true,cat:"Portfolio",inputs:[],
 run:p=>{const L=TASKS.filter(t=>t.own===p.name&&t.pct<100);const old=L.map(t=>[t.id,t.own]);L.forEach(t=>t.own=p.handoff);const w=G(()=>workload(p.handoff).pct,0);return{ok:true,summary:L.length+" open task"+(L.length===1?"":"s")+" handed from "+p.name+" to "+p.handoff,undo:{k:"handoff",old},card:{t:"result",tone:w>95?"warn":"good",title:L.length+" task"+(L.length===1?"":"s")+" handed off",sub:p.handoff+" is now at "+w+"% load"}}},undo:u=>{u.old.forEach(([id,o])=>{const t=TASKS.find(x=>x.id===id);if(t)t.own=o});return"Tasks returned to their owner"}});

/* ---- 12. chain plans ---- */
function onboardSteps(p){const nm=p.name,mg=p.mgr||"Maya Ortiz";const L=[{id:"s1",label:"Create the identity and mailbox for "+nm,tool:"acct.create",owner:{kind:"auto",who:"Oukala automation"},params:{name:nm,start:p.start,mgr:mg,role:p.role,team:p.team,loc:p.loc,worker:p.worker},dep:[]},
 {id:"s2",label:"Assign Microsoft 365 E5 and standard groups",tool:"license.assign",owner:{kind:"auto",who:"Oukala automation"},params:{name:nm},dep:["s1"]},
 {id:"s3",label:"Order a "+(p.laptop||"Standard 14-inch")+" laptop",tool:"request.order",owner:{kind:"human",who:"Northwind Managed Services"},params:{item:"laptop",who:nm,model:p.laptop||"Standard 14-inch",memory:"As shipped",reason:"New hire",deliver:p.loc==="Remote"?"Home (remote)":"Parker HQ desk",just:p.laptop==="Developer 16-inch"?"New hire in a build role needs the Developer model.":"",monitor:true},dep:["s1"],
  sub:["Manager approval","Autopilot profile prepared","Shipped or staged at the desk","Delivered and confirmed by "+nm]}];
 if(p.phone)L.push({id:"s4",label:"Order an iPhone 16",tool:"request.order",owner:{kind:"human",who:"Northwind Managed Services"},params:{item:"phone",who:nm,model:"iPhone 16",deliver:"Parker HQ desk"},dep:["s1"],sub:["Manager approval","Enrolled in Intune","Delivered"]});
 L.push({id:"s5",label:"Request access: Standards Platform (Read)",tool:"access.grant",owner:{kind:"human",who:"Chief Editor"},params:{who:nm,system:"Standards Platform",level:"Read",why:"Standard access for new hires in "+(p.team||"the team")},dep:["s1"],sub:["Data owner approves","Group added in Entra ID"]},
 {id:"s6",label:"Issue a building badge and desk",tool:"badge.request",owner:{kind:"human",who:"Tom Becker"},params:{name:nm,start:p.start},dep:["s1"]},
 {id:"s7",label:"Enroll in security awareness and confidentiality training",tool:"training.enroll",owner:{kind:"auto",who:"Oukala automation"},params:{name:nm},dep:["s1"]},
 {id:"s8",label:"Book day-one orientation, 1:1 and buddy intro",tool:"calendar.book",owner:{kind:"agent",who:"First Officer"},params:{name:nm,start:p.start,mgr:mg},dep:["s1"]},
 {id:"s9",label:"Send the welcome message and a status summary to "+mg,tool:"notify.send",owner:{kind:"auto",who:"Oukala automation"},params:{name:nm,mgr:mg},dep:["s2","s6","s7","s8"]});
 return L}
T({id:"onboard.user",name:"Onboard a new user",cat:"Fulfillment",desc:"A multi-step plan: identity and mailbox, licenses, laptop and phone, system access, badge, training, calendar and welcome. Runs as an activity with sub-plans, approvals and owners.",perm:"access.grant",write:true,risk:"medium",confirm:"ask",
 kw:[[/\bonboard(ing)?\b/,8],[/\b(new hire|new starter|joiner)\b.{0,30}\b(set ?up|start|provision)/,6],[/\bset up\b.{0,20}\bnew (employee|hire|user)/,7]],ex:["Onboard Marcus Webb as a standards editor starting Oct 26"],
 inputs:[{k:"name",label:"Full name",type:"text",req:true},{k:"start",label:"Start date",type:"date",req:true},{k:"mgr",label:"Manager",type:"person",req:true},{k:"role",label:"Role",type:"text",def:"Standards editor"},{k:"team",label:"Team",type:"select",opts:()=>TEAMS.filter(t=>t.id!=="agents").map(t=>[t.n,t.n]),def:"Editors"},{k:"worker",label:"Worker type",type:"chips",opts:["Employee","Contractor"],def:"Employee"},{k:"loc",label:"Location",type:"chips",opts:["Parker HQ","Remote"],def:"Parker HQ"},{k:"laptop",label:"Laptop",type:"chips",opts:["Standard 14-inch","Developer 16-inch"],def:"Standard 14-inch"},{k:"phone",label:"Needs a phone",type:"toggle"}],
 prefill:(E,q,c)=>{const o={};const m=/[Oo]nboard(?:ing)?\s+(?:a\s+new\s+(?:user|hire|employee|contractor)\s+(?:named|called)?\s*)?([A-Z][a-z]+(?:\s+[A-Z][a-z'-]+){1,2})/.exec(q)||/(?:hire|user|employee|starter)\s+(?:named|called)?\s*([A-Z][a-z]+(?:\s+[A-Z][a-z'-]+){1,2})/.exec(q);if(m)o.name=m[1];const role=/\bas (?:an? |the )?([a-z][a-z ]{3,40}?)(?:\s+(?:starting|on|reporting|for|in)\b|$|[,.])/i.exec(q);if(role)o.role=role[1].trim().replace(/^./,x=>x.toUpperCase());if(E.date)o.start=E.date;const mg=E.persons.find(n=>n!==o.name);if(/report(?:ing)? to|manager|under/i.test(q)&&mg)o.mgr=mg;else if(mg&&!/\bfor\b/.test(q))o.mgr=mg;else o.mgr=c.subj&&c.subj!==ME_NAME?c.subj:(mg||"");if(/contractor/i.test(q))o.worker="Contractor";if(/remote/i.test(q))o.loc="Remote";if(/developer|engineer/i.test(q))o.laptop="Developer 16-inch";if(/phone/i.test(q))o.phone=true;return o},
 plan:onboardSteps,
 cost:p=>(PRICES.model.laptop[p.laptop||"Standard 14-inch"]||1450)+320+(p.phone?829:0),
 preview:p=>{const ex=G(()=>(window.REQREG||[]).find(r=>r.item==="onboarding"&&r.vals&&r.vals.name===p.name),null);return(ex?"<b>Heads up:</b> an onboarding request "+H(ex.id)+" for "+H(p.name)+" already exists ("+H(ex.state)+"). Continue only if this is a different person. ":"")+"Plan covers 9 steps, about <b>"+mon(TBY("onboard.user").cost(p))+"</b> of hardware, approvals from the manager and the data owner."},
 validate:p=>pd(p.start)<pd(TODAY)?{start:"Start date is in the past"}:null,run:()=>({ok:true,summary:"Plan only"})});
function offboardSteps(p){const nm=p.name;return[{id:"s1",label:"Schedule sign-in disable and revoke sessions for "+nm,tool:"access.remove",owner:{kind:"auto",who:"Oukala automation"},params:{name:nm,last:p.last},dep:[]},
 {id:"s2",label:"Hand off open work to "+p.handoff,tool:"handoff.work",owner:{kind:"human",who:p.handoff},params:{name:nm,handoff:p.handoff},dep:[]},
 {id:"s3",label:"Arrange device collection and wipe",tool:"device.return",owner:{kind:"human",who:"Northwind Managed Services"},params:{name:nm,last:p.last},dep:[]},
 {id:"s4",label:"Send the exit checklist and status to the manager",tool:"notify.send",owner:{kind:"auto",who:"Oukala automation"},params:{name:nm,mgr:mgrOf(nm)},dep:["s1","s2","s3"]}]}
T({id:"offboard.user",name:"Offboard a user",cat:"Fulfillment",desc:"Plan: disable sign-in at the end time, hand off work, collect devices, send the checklist. High risk, so a person always approves.",perm:"access.grant",write:true,risk:"high",confirm:"always",
 kw:[[/\boffboard(ing)?\b/,8],[/\b(leaving|last day|terminate|departure|end of contract)\b.{0,30}\b(access|devices?|laptop)/,6]],
 inputs:[{k:"name",label:"Who is leaving",type:"person",req:true},{k:"last",label:"Last day",type:"date",req:true},{k:"handoff",label:"Hand work to",type:"person",req:true}],
 prefill:(E,q)=>({name:E.persons[0]||"",last:E.date||"",handoff:E.persons[1]||""}),plan:offboardSteps,gates:p=>[{who:mgrOf(p.name),why:"Manager confirms the departure",pol:"G1"}],run:()=>({ok:true,summary:"Plan only"})});
T({id:"search.records",name:"Search the platform",cat:"Insight",desc:"Searches every registered record and returns citations.",perm:"read",write:false,risk:"low",confirm:"never",kw:[[/\b(find|search|look for|look up)\b/,4]],inputs:[{k:"q",label:"Query",type:"text",req:true}],prefill:(E,q)=>({q:q.replace(/^(find|search( for)?|look (for|up))\s+/i,"")}),run:p=>{const hits=searchHits(p.q);return{ok:true,summary:hits.length+" matching records",card:{t:"cites",items:hits}}}});
function searchHits(q,n){const toks=String(q).toLowerCase().split(/[^a-z0-9.-]+/).filter(w=>w.length>1&&!/^(the|and|for|how|what|who|why|show|find|search|about)$/.test(w));if(!toks.length)return[];let ix=[];try{ix=searchIndex()}catch(e){}const out=[];ix.forEach(r=>{const hay=(r.t+" "+r.m+" "+(r.k||"")).toLowerCase();let s=0;toks.forEach(t=>{if(hay.indexOf(t)>=0)s++});if(s>=Math.max(1,Math.ceil(toks.length*.6))&&r.g!=="Go to")out.push({r,s})});out.sort((a,b)=>b.s-a.s);return out.slice(0,n||6).map(x=>({t:x.r.t,src:x.r.g+" · "+x.r.m,go:x.r.f}))}
CX.searchHits=searchHits;
